Product search_product(Product product) {
    int low = 0;
    int high = products.size() - 1;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (products[mid] == product) {
            return products[mid];
        } else if (products[mid] < product) {
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    return Product();
}

std::map<std::string, double> generate_monthly_report(const std::vector<Claim>& claims) {
   std::map<std::string, double> report;
   for (const auto& claim : claims) {
     report[claim.provider]; // Add provider to report
     report[claim.provider] += claim.amount; // Add payment to report
   }
   return report;
}

